function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){function h(s){var x=0x811c9dc5;for(var i=0;i<s.length;i++){x^=s.charCodeAt(i);x=Math.imul(x,0x01000193);}return(x>>>0).toString(16);}function compute(){var R=prng(seed*399999+67);var acc=0;for(var i=0;i<1000;i++)acc+=R();return acc.toFixed(6);}var r1=compute(),r2=compute();return{run1:r1,run2:r2,hash:h(r1),reproducible:r1===r2};}
var SEED = 95501;
console.log(JSON.stringify(demoRun(SEED), null, 1));

